package com.edgecloud.alert.entity;
import java.time.Instant; import java.util.UUID; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import jakarta.persistence.*;
@Entity @Table(name="maintenance_window_audit",indexes=@Index(name="idx_maintenance_audit_window",columnList="project_id,maintenance_window_id,occurred_at"))
public class MaintenanceWindowAudit {@Id @GeneratedValue(strategy=GenerationType.UUID) @JdbcTypeCode(SqlTypes.CHAR) @Column(length=36) private UUID id;@JdbcTypeCode(SqlTypes.CHAR) @Column(name="project_id",nullable=false,length=36) private UUID projectId;@JdbcTypeCode(SqlTypes.CHAR) @Column(name="maintenance_window_id",nullable=false,length=36) private UUID maintenanceWindowId;@JdbcTypeCode(SqlTypes.CHAR) @Column(name="actor_user_id",nullable=false,length=36) private UUID actorUserId;@Column(nullable=false,length=16) private String action;@Column(name="occurred_at",nullable=false) private Instant occurredAt;protected MaintenanceWindowAudit(){}public MaintenanceWindowAudit(MaintenanceWindow w,UUID actor,String action){projectId=w.getProjectId();maintenanceWindowId=w.getId();actorUserId=actor;this.action=action;occurredAt=Instant.now();}}
